<script setup lang="ts">
import { computed,ref } from 'vue'
import { usePlatform } from '../stores/platform'
import { useContinuity } from '../stores/continuity'
import PageHead from '../components/PageHead.vue'
import Modal from '../components/Modal.vue'
import Badge from '../components/Badge.vue'
const s=usePlatform(),c=useContinuity(),planId=ref(''),open=ref(false),type=ref('任务协调'),subject=ref(''),note=ref(''),reply=ref(''),active=ref('')
const plans=computed(()=>s.data.plans.filter(p=>s.can('development')||p.leadId===s.personId)),selected=computed(()=>plans.value.find(p=>p.id===planId.value)||plans.value[0]),questions=computed(()=>s.data.questions.filter(q=>q.taskId===selected.value?.id)),records=computed(()=>c.data.coordination.filter(r=>r.planId===selected.value?.id))
function create(){s.run(()=>{c.coordinate(selected.value!.id,type.value,subject.value,note.value);open.value=false;subject.value='';note.value=''})}
</script>
<template><PageHead title="项目协调" subtitle="汇集负责项目的任务进度、审核状态和事项处理记录。" eyebrow="题库建设 / 项目管理"><button class="button primary" :disabled="!selected" @click="open=true">登记事项</button></PageHead><section class="panel"><div class="filter-bar"><label class="inline-label">负责项目<select v-model="planId"><option value="" disabled>请选择项目</option><option v-for="p in plans" :value="p.id">{{p.name}}</option></select></label><span>{{selected?.name||'暂无负责项目'}}</span></div><template v-if="selected"><div class="mini-metrics"><div><span>目标题量</span><strong>{{selected.target}}</strong></div><div><span>已开发</span><strong>{{questions.length}}</strong></div><div><span>已入库</span><strong>{{questions.filter(q=>q.status==='已入库').length}}</strong></div><div><span>待处理事项</span><strong>{{records.filter(r=>r.status==='待处理').length}}</strong></div></div><table><thead><tr><th>任务</th><th>命题人员</th><th>审核状态</th><th>当前处理人</th></tr></thead><tbody><tr v-for="q in questions"><td>{{q.title}}<small>{{q.id}} · V{{q.version}}</small></td><td>{{q.author}}</td><td><Badge :text="q.status"/></td><td>{{s.people.find(p=>p.id===q.assignments?.[q.status])?.name||q.author}}</td></tr></tbody></table></template></section><section class="panel spaced"><div class="panel-head"><h3>事项处理记录</h3></div><table><thead><tr><th>事项</th><th>登记人</th><th>状态</th><th>处理意见</th><th>操作</th></tr></thead><tbody><tr v-for="r in records"><td>{{r.subject}}<small>{{r.type}} · {{r.note}}</small></td><td>{{r.actor}}<small>{{r.time}}</small></td><td>{{r.status}}</td><td>{{r.reply||'待处理'}}<small>{{r.handledBy}}</small></td><td><button v-if="r.status==='待处理'" class="text-button" @click="active=r.id;reply=''">处理</button></td></tr></tbody></table><p v-if="!records.length" class="muted">暂无协调事项。</p></section><Modal v-if="open" title="登记项目事项" @close="open=false"><label class="field">类别<select v-model="type"><option>任务协调</option><option>特殊申请</option></select></label><label class="field">事项<input v-model="subject"/></label><label class="field">说明<textarea v-model="note" rows="4"/></label><p class="muted">特殊申请仅登记与处理意见；具体审批规则待确认，不能跳过现有审核和入库步骤。</p><template #footer><button class="button primary" @click="create">保存事项</button></template></Modal><Modal v-if="active" title="记录处理意见" @close="active=''"><label class="field">处理意见<textarea v-model="reply" rows="4"/></label><template #footer><button class="button primary" @click="s.run(()=>{c.resolve(active,reply);active=''})">完成处理</button></template></Modal></template>
